-- Owner decision (2026-09-29): remove the La Trinidad route's "Km 4" stop.
--
-- Its pin, hand-placed in the original sketch, sat on a residential road in
-- Dreamland-Piripin Bato about 690 m off Halsema Highway, and the road-snapped
-- line ran a 2.1 km dead end up Piripin-Bato Road to reach it and back. The
-- stop is deleted and PLZ-LTR takes the direct road path regenerated by
-- scripts/snap-routes.mjs (11.83 km -> 6.95 km). Without Km 4 the line reaches
-- Magsaysay Avenue on a neighbouring street, so that stop moves 74.7 m onto it.
-- The remaining stops keep their seq numbers (1, 2, 4, 5, 6) and ids.
--
-- Mirrors supabase/seed.sql. Idempotent: a re-run deletes nothing and rewrites
-- the same values. Touches only PLZ-LTR. After applying, flush the Redis
-- geo/transit/routes* keys.
DO $$
DECLARE
  n integer;
BEGIN
  DELETE FROM "transit_stops"
  WHERE "route_id" = (SELECT "id" FROM "transit_routes" WHERE "code" = 'PLZ-LTR') AND "seq" = 3 AND "name" = 'Km 4';

  UPDATE "transit_routes"
