  WHERE "code" = 'PLZ-LTR';
  GET DIAGNOSTICS n = ROW_COUNT;
  IF n <> 1 THEN RAISE EXCEPTION 'expected 1 transit_routes row updated, got %', n; END IF;

  UPDATE "transit_routes"
  SET "geom_z12" = ST_Simplify("geom", 0.0012), "geom_z14" = ST_Simplify("geom", 0.0004)
  WHERE "code" = 'PLZ-LTR';

  UPDATE "transit_stops"
  SET "geom" = ST_SetSRID(ST_MakePoint(120.59317, 16.42084), 4326)
  WHERE "route_id" = (SELECT "id" FROM "transit_routes" WHERE "code" = 'PLZ-LTR') AND "seq" = 2 AND "name" = 'Magsaysay Avenue';
  GET DIAGNOSTICS n = ROW_COUNT;
  IF n <> 1 THEN RAISE EXCEPTION 'expected 1 Magsaysay Avenue stop updated, got %', n; END IF;

  SELECT count(*) INTO n FROM "transit_stops" WHERE "route_id" = (SELECT "id" FROM "transit_routes" WHERE "code" = 'PLZ-LTR');
  IF n <> 5 THEN RAISE EXCEPTION 'expected 5 PLZ-LTR stops, found %', n; END IF;
END $$;
